import uuid

import psycopg
from fastapi.testclient import TestClient

from apps.api.main import app
from scripts.verify_audit_chain import verify_audit_chains
from tests.helpers import seed_membership, seed_tenant, seed_user


def test_audit_chain_verifies_after_phase1_operations(
    postgres_url: str,
    db_conn: psycopg.Connection,
):
    """Verifies that all audit events generated by Phase 1 endpoints form a valid hash chain."""
    client = TestClient(app)

    tenant_id = seed_tenant(db_conn, "Cabinet Audit Verification")
    user_id = seed_user(db_conn, "sub-audit-user", "audit@cabinet.ma", "Audit Verifier")
    seed_membership(db_conn, user_id, tenant_id, role="accountant")

    headers = {
        "X-Identity-Subject": "sub-audit-user",
        "Idempotency-Key": str(uuid.uuid4()),
    }

    # 1. API operation: Create client company -> emits client.create audit event
    res_c = client.post(
        "/v1/client-entities",
        headers=headers,
        json={"legal_name": "Audit Company SARL", "ice": "999999999999999"},
    )
    assert res_c.status_code == 201
    client_id = res_c.json()["id"]

    # 2. API operation: Seed CGNC chart -> emits chart.seed_cgnc audit event
    res_s = client.post(
        f"/v1/client-entities/{client_id}/chart-accounts/seed-cgnc",
        headers={**headers, "Idempotency-Key": str(uuid.uuid4())},
    )
    assert res_s.status_code == 200

    # 3. API operation: Open accounting period -> emits period.open audit event
    res_p = client.post(
        f"/v1/client-entities/{client_id}/periods",
        headers={**headers, "Idempotency-Key": str(uuid.uuid4())},
        json={
            "period_code": "2026-09",
            "starts_on": "2026-09-01",
            "ends_on": "2026-09-30",
            "fiscal_year_end": "2026-12-31",
        },
    )
    assert res_p.status_code == 201

    # 4. Verify audit chains across the database
    assert verify_audit_chains(postgres_url, tenant_id=tenant_id, fail_on_empty=True) is True

